import{_ as l,H as n,f as e,i as r}from"./chunks/framework.BH2BK_3i.js";const s=JSON.parse('{"title":"02-微服务全家桶：走进SpringCloud的世界","description":"","frontmatter":{},"headers":[{"level":2,"title":"大话 Spring Cloud","slug":"大话-spring-cloud","link":"#大话-spring-cloud","children":[]},{"level":2,"title":"Spring Cloud 组件库的朝代更替","slug":"spring-cloud-组件库的朝代更替","link":"#spring-cloud-组件库的朝代更替","children":[]},{"level":2,"title":"Spring Cloud 全家桶组件库","slug":"spring-cloud-全家桶组件库","link":"#spring-cloud-全家桶组件库","children":[]},{"level":2,"title":"Spring Cloud 版本更新策略","slug":"spring-cloud-版本更新策略","link":"#spring-cloud-版本更新策略","children":[]},{"level":2,"title":"总结","slug":"总结","link":"#总结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"SpringCloud微服务项目实战/02-微服务全家桶：走进SpringCloud的世界.md","filePath":"SpringCloud微服务项目实战/02-微服务全家桶：走进SpringCloud的世界.md","lastUpdated":1795535212000}'),p={name:"SpringCloud微服务项目实战/02-微服务全家桶：走进SpringCloud的世界.md"};function o(t,i,a,u,g,d){return n(),e("div",null,[...i[0]||(i[0]=[r('<h1 id="_02-微服务全家桶-走进springcloud的世界" tabindex="-1">02-微服务全家桶：走进SpringCloud的世界 <a class="header-anchor" href="#_02-微服务全家桶-走进springcloud的世界" aria-label="Permalink to &quot;02-微服务全家桶：走进SpringCloud的世界&quot;">​</a></h1><p>你好，我是姚秋辰。</p><p>上一节课，我向你介绍了微服务架构的特点和优势。今天我就来带你了解 Spring Cloud 框架，看一看被称为微服务全家桶的 Spring Cloud 提供了哪些强大的工具。</p><p>通过今天的学习，你将会了解 Spring Cloud 框架的功能定位，以及它和 Spring Boot 之间的关系。除此之外，我还会详细讲解 Spring Cloud 的发展历史，并介绍 Netflix 和 Alibaba 两大核心组件库，以及 Spring Cloud 的版本更新策略。这样一来，你就对 Spring Cloud 框架有了一个全面的认识。</p><p>那我首先来带你了解一下什么是 Spring Cloud。</p><h2 id="大话-spring-cloud" tabindex="-1">大话 Spring Cloud <a class="header-anchor" href="#大话-spring-cloud" aria-label="Permalink to &quot;大话 Spring Cloud&quot;">​</a></h2><p>Spring Cloud 可谓出身名门，它由 Spring 开源社区主导孵化的，专门为了解决微服务架构难题而诞生的一款微“微服务全家桶”框架。难能可贵的是，Spring Cloud 走了一条博采众家之长的道路，除了 Spring 开源社区的研发力量以外，它还吸纳了很多业界一线互联网大厂的开源组件为己用，将这些经过大厂真实业务锤炼的组件孵化成为了 Spring Cloud 组件的一部分。</p><p>我们通过 Spring 社区发布的一张简化的架构图来看一下 Spring Cloud 的技能加点。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SpringCloud%E5%BE%AE%E6%9C%8D%E5%8A%A1%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%98/images/02-%25E5%25BE%25AE%25E6%259C%258D%25E5%258A%25A1%25E5%2585%25A8%25E5%25AE%25B6%25E6%25A1%25B6/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SpringCloud%E5%BE%AE%E6%9C%8D%E5%8A%A1%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%98/images/02-%25E5%25BE%25AE%25E6%259C%258D%25E5%258A%25A1%25E5%2585%25A8%25E5%25AE%25B6%25E6%25A1%25B6/1.png" alt=""></a></p><ul><li>Spring社区发布的一张简化的架构图</li></ul><p>在上面这幅图中，我们可以看到有几个 Spring Boot Apps 的应用集群，这就是经过拆分后的微服务。Spring Cloud 和 Spring Boot 达成了一种默契的配合：Spring Boot 主内，通过自动装配和各种开箱即用的特性，搞定了数据层访问、RESTful 接口、日志组件、内置容器等等基础功能，让开发人员不费吹灰之力就可以搭建起一个应用；Spring Cloud 主外，在应用集群之外提供了各种分布式系统的支持特性，帮助你轻松实现负载均衡、熔断降级、配置管理等诸多微服务领域的功能。</p><p>从 Spring Boot 和 Spring Cloud 的分工中我们可以看出，Spring Boot 忙活的是底层的柴米油盐酱醋茶，Spring Boot 后勤保障做得好，才能让 Spring Cloud 毫无顾虑地投身于微服务的星辰大海，两者合二为一完整构建了微服务领域的全家桶解决方案。</p><p>到这里，相信你已经可以理解 Spring Boot 和 Spring Cloud 的侧重点，以及 Spring Cloud 的功能定位。那么接下来，让我带你去了解一下 Spring Cloud 内部都有哪些重要组件。</p><h2 id="spring-cloud-组件库的朝代更替" tabindex="-1">Spring Cloud 组件库的朝代更替 <a class="header-anchor" href="#spring-cloud-组件库的朝代更替" aria-label="Permalink to &quot;Spring Cloud 组件库的朝代更替&quot;">​</a></h2><p>在我们开始了解 Spring Cloud 组件库之前，我得先介绍在 Spring Cloud 历史上举足轻重的两家公司 Netflix 和 Alibaba，以及它们的恩怨情仇。这两家公司分别为开源社区贡献了 SpringCloud Netflix 组件库和 Spring Cloud Alibaba 组件库。</p><p>说起 Netflix 可能你并不知道，但提起《纸牌屋》你一定看过或者听过，这部高分美剧就是由这家我们俗称“奈飞”的公司出品的。Netflix 是一家美国的流媒体巨头，它靠着自己强大的技术实力，开发沉淀了一系列优秀的组件，这些组件经历了 Netflix 线上庞大业务规模的考验，功能特性和稳定性过硬。如 Eureka 服务注册中心、Ribbon 负载均衡器、Hystrix 服务容错组件等。后来发生的故事可能你已经猜到了，Netflix 将这些组件贡献给了 Spring 开源社区，构成了 Netflix 组件库。可以这么说，在 Spring Cloud 的早期阶段，是 Netflix 打下了的半壁江山。</p><p>Netflix 和 Spring Cloud 度过了蜜月期之后，矛盾就逐渐发生了。先是 Eureka 2.0 开源计划的搁浅，而后 Netflix 宣布 Hystrix 进入维护状态，Eureka 和 Hystrix 这两款 Netflix 组件库的明星项目停止了新功能的研发，Spring 社区不得不开始思考替代方案，在后续的新版本中走向了“去 Netflix 化”。以至于 Netflix 的网关组件 Zuul 2.0 历经几次跳票千呼万唤始出来后，SpringCloud 社区已经不打算集成 Zuul 2.0，而是掏出了自己的 Gateway 网关。在最新版本的Spring Cloud 中，Netflix 的踪迹已经逐渐消散，只有 Eureka 组件形单影只待在 Netflix 组件库中，回忆着昔日的辉煌。</p><p>Spring Cloud Alibaba 是由 Alibaba 贡献的组件库，随着阿里在开源路线上的持续投入，近几年阿里系在开源领域的声音非常响亮。Spring Cloud Alibaba 凝聚了阿里系在电商领域超高并发经验的重量级组件，保持了旺盛的更新活力，成为了 Spring Cloud 社区的一股新生代力量，逐渐取代了旧王 Netflix 的江湖地位。Spring Cloud Alibaba 组件秉承了“大而全”的特点，就像一个大中台应用一般包罗万象，在功能特性的丰富程度上做到了应有尽有，待我们学到Spring Cloud 章节后你就能体会到了。这也是本课程选择 Spring Cloud Alibaba 组件的一个重要原因。</p><h2 id="spring-cloud-全家桶组件库" tabindex="-1">Spring Cloud 全家桶组件库 <a class="header-anchor" href="#spring-cloud-全家桶组件库" aria-label="Permalink to &quot;Spring Cloud 全家桶组件库&quot;">​</a></h2><p>我整理归纳了一个表格，将 Spring Cloud 中的核心组件库根据功能点做了分类，让你对每个特性功能的可选组件一目了然，其中红色加粗的，是我们在课程实战环节将要集成的组件，你可以参考一下。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SpringCloud%E5%BE%AE%E6%9C%8D%E5%8A%A1%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%98/images/02-%25E5%25BE%25AE%25E6%259C%258D%25E5%258A%25A1%25E5%2585%25A8%25E5%25AE%25B6%25E6%25A1%25B6/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SpringCloud%E5%BE%AE%E6%9C%8D%E5%8A%A1%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%98/images/02-%25E5%25BE%25AE%25E6%259C%258D%25E5%258A%25A1%25E5%2585%25A8%25E5%25AE%25B6%25E6%25A1%25B6/2.png" alt=""></a></p><p>上面表格中列出的是业务开发过程中的常用功能性组件，除了这些以外，Spring Cloud 官方还提供了很多可扩展组件，比如用来支持构建集群的 Spring Cloud Cluster、提供安全特性支持的 Spring Cloud Security、云原生的流处理数据管道 Spring Cloud Data Flow 等等，你可以在这个Spring Cloud 官方文档中找到完整的列表。</p><p>如果你想了解 Spring Cloud Alibaba 组件的更多细节，我推荐你阅读 spring-cloud-alibaba 的官方 GitHub 首页或者开源社区文档。</p><p>到这里，我们对 Spring Cloud 的核心组件库有了一个比较全面的了解，接下来，我带你去了解一下 Spring Cloud 的版本更新策略。</p><h2 id="spring-cloud-版本更新策略" tabindex="-1">Spring Cloud 版本更新策略 <a class="header-anchor" href="#spring-cloud-版本更新策略" aria-label="Permalink to &quot;Spring Cloud 版本更新策略&quot;">​</a></h2><p>大部分开源项目以数字版本进行更新迭代，Spring Cloud 在诞生之初就别出心裁使用了字母序列，以字母 A 开头，按顺序使用字母表中的字母标识重大迭代发布的大版本号。</p><p>我整理了一个表格，包含了 Spring Cloud 编年史各个版本的代号以及 Release 版的发布时间，我们来感受一下 Spring Cloud 的更新节奏：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SpringCloud%E5%BE%AE%E6%9C%8D%E5%8A%A1%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%98/images/02-%25E5%25BE%25AE%25E6%259C%258D%25E5%258A%25A1%25E5%2585%25A8%25E5%25AE%25B6%25E6%25A1%25B6/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SpringCloud%E5%BE%AE%E6%9C%8D%E5%8A%A1%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%98/images/02-%25E5%25BE%25AE%25E6%259C%258D%25E5%258A%25A1%25E5%2585%25A8%25E5%25AE%25B6%25E6%25A1%25B6/3.png" alt=""></a></p><p>从上面的表格中我们可以看出，Spring Cloud 自 2015 年发布之始就保持了极其旺盛的生命力，早期版本每半年就有一个大的版本号迭代，即便发展至今，也保持着几乎一年一升版的快速更新节奏。正是由于开源社区的持续输出，以及像 Alibaba 这类大型公司的助力，才有了今天微服务领域最为完善的 Spring Cloud 全家桶组件库。</p><p>我们看完了 Spring Cloud 的大版本迭代更新策略，在大版本发布之前，还要经历很多小版本的迭代，接下来我带你了解一下 Spring Cloud 的小版本更新策略。如果你不清楚这里面的门道，很容易就会误用非稳定版本。</p><ul><li><p>SNAPSHOT 版本：正在开发中的快照版本，例如 2021.0.0-SNAPSHOT，快照版代表当前分支最新的代码进度，也是更新最为频繁的小版本类型，不推荐在线上正式环境使用；</p></li><li><p>Milestone 版本：在大版本正式发布前的里程碑版本，例如 2021.0.0-M1，M1 代表当前大版本的第一个里程碑版本，M2 代表第二个迭代里程碑，以此类推。在正式版本发布之前要经历多个里程碑的迭代，像 Spring Cloud Finchley 版足足经历了 9 个 M 版本之后，才过渡到了 RC 版。同样地，我也不推荐你在正式项目中使用 Milestone 版本；</p></li><li><p>Release Candidate 版本：这就是我们俗称的 RC 版，例如 2021.0.0-RC1。当一个版本迭代到 RC 版的时候，意味着离正式发布已经不远了。但是你要注意，RC 版是发布前的候选版本，走到这一步通常已经没有新的功能开发，RC 主要目的是开放出来让大家试用并尽量修复严重 Bug。</p></li><li><p>Release 版：稳定的正式发布版，比如 2020.0.1。你可以在自己的线上业务中放心使用Release 稳定版。</p></li></ul><p>到这里，我们就完整了解了 Spring Cloud 的发展历史、核心组件库、版本更新策略。现在，我们来回顾一下这节课的重点内容。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>今天我带你了解了 Spring Cloud 框架的定位和它的核心组件库。以史为镜，我们了解了Netflix 组件库和 Alibaba 组件库朝代更替的背景故事，以帮助我们在做技术选型的时候尽可能避开已经进入“维护状态”的组件。</p><p>此外，我想再和你分享一些新旧工具应用的经验。我周围很多的技术人员在做项目的时候容易进入一个误区，那就是“为新而新”，什么意思呢？每当一个新版本出来的时候，他们就迫不及待地把自己的业务升级到最新版本，盲目追新，殊不知这样做很容易翻车。作为一名老司机，我推荐你这样做：当你心仪的框架有重大版本更新时，我还是建议你先按兵不动，等大版本做了一两次迭代之后，明显的 Bug 修复得七七八八了，再应用到自己的项目中也不迟。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>当你考虑给自己的项目做底层技术框架升版的时候，你会基于哪些因素做出“升级版本”的决定呢？欢迎你与我交流讨论，我在留言区等你。</p><p>好啦，这节课就结束啦。也欢迎你把这节课分享给更多对 Spring Cloud 感兴趣的朋友。我是姚秋辰，我们下节课再见！</p>',38)])])}const S=l(p,[["render",o]]);export{s as __pageData,S as default};
